<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Bouncing Ball Playground</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0d1220;
      --panel: #151d31;
      --text: #e8efff;
      --muted: #8d9ab8;
      --accent: #6ee7ff;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      background:
        radial-gradient(circle at 50% 15%, #1c2c4e 0, transparent 42%),
        var(--bg);
      color: var(--text);
      font-family: system-ui, sans-serif;
    }

    .wrap {
      width: min(92vw, 720px);
      text-align: center;
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.5rem, 4vw, 2.2rem);
      letter-spacing: .04em;
    }

    p {
      margin: 0 0 18px;
      color: var(--muted);
    }

    .stage {
      padding: 12px;
      border: 1px solid #2b3b5f;
      border-radius: 18px;
      background: #10182a;
      box-shadow: 0 18px 50px #0008, inset 0 0 30px #172848;
    }

    canvas {
      display: block;
      width: 100%;
      min-width: 400px;
      aspect-ratio: 4 / 3;
      height: auto;
      border-radius: 10px;
      background: #080d18;
      cursor: crosshair;
      touch-action: none;
    }

    .controls {
      display: flex;
      justify-content: center;
      gap: 10px;
      margin-top: 14px;
      flex-wrap: wrap;
    }

    button {
      border: 1px solid #38527d;
      border-radius: 999px;
      padding: 9px 18px;
      color: var(--text);
      background: var(--panel);
      font: inherit;
      cursor: pointer;
      transition: transform .12s, background .12s, border-color .12s;
    }

    button:hover {
      background: #223252;
      border-color: var(--accent);
    }

    button:active { transform: scale(.95); }
  </style>
</head>
<body>
  <main class="wrap">
    <h1>Bouncing Ball Playground</h1>
    <p>Click anywhere in the arena to launch a ball.</p>

    <div class="stage">
      <canvas id="sim" width="640" height="480"></canvas>
      <div class="controls">
        <button id="drop">Drop Ball</button>
        <button id="play">Pause</button>
        <button id="clear">Clear</button>
      </div>
    </div>
  </main>

  <script>
    (() => {
      const canvas = document.getElementById("sim");
      const ctx = canvas.getContext("2d");
      const w = canvas.width;
      const h = canvas.height;
      const gravity = 0.48;
      const restitution = 0.84;
      const ballsList = [];
      let running = true;
      let lastTime = performance.now();

      function clampBall(ball) {
        ball.x = Math.max(ball.r, Math.min(w - ball.r, ball.x));
        ball.y = Math.max(ball.r, Math.min(h - ball.r, ball.y));
      }

      function addBall(x, y, vx = 0, vy = 0, r = 14) {
        r = Math.max(3, Math.min(Math.min(w, h) / 2 - 1, Number(r) || 14));
        const ball = {
          x: Number.isFinite(x) ? x : w / 2,
          y: Number.isFinite(y) ? y : r,
          vx: Number.isFinite(vx) ? vx : 0,
          vy: Number.isFinite(vy) ? vy : 0,
          r
        };
        clampBall(ball);
        ballsList.push(ball);
        draw();
        return ball;
      }

      function step(dt = 1) {
        dt = Math.max(0, Number(dt) || 0);
        const slices = Math.max(1, Math.ceil(dt / 0.35));
        const slice = dt / slices;

        for (let s = 0; s < slices; s++) {
          for (const ball of ballsList) {
            ball.vy += gravity * slice;
            ball.x += ball.vx * slice;
            ball.y += ball.vy * slice;

            if (ball.x - ball.r < 0) {
              ball.x = ball.r;
              if (ball.vx < 0) ball.vx = -ball.vx * restitution;
            } else if (ball.x + ball.r > w) {
              ball.x = w - ball.r;
              if (ball.vx > 0) ball.vx = -ball.vx * restitution;
            }

            if (ball.y - ball.r < 0) {
              ball.y = ball.r;
              if (ball.vy < 0) ball.vy = -ball.vy * restitution;
            } else if (ball.y + ball.r > h) {
              ball.y = h - ball.r;
              if (ball.vy > 0) ball.vy = -ball.vy * restitution;
            }
          }
        }
        draw();
      }

      function clear() {
        ballsList.length = 0;
        draw();
      }

      function draw() {
        ctx.clearRect(0, 0, w, h);

        const gradient = ctx.createLinearGradient(0, 0, 0, h);
        gradient.addColorStop(0, "#0b1325");
        gradient.addColorStop(1, "#101d35");
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, w, h);

        ctx.strokeStyle = "#263b62";
        ctx.lineWidth = 2;
        ctx.strokeRect(1, 1, w - 2, h - 2);

        for (const ball of ballsList) {
          ctx.beginPath();
          ctx.arc(ball.x + 3, ball.y + 5, ball.r, 0, Math.PI * 2);
          ctx.fillStyle = "#0007";
          ctx.fill();

          const g = ctx.createRadialGradient(
            ball.x - ball.r * .35, ball.y - ball.r * .4, 1,
            ball.x, ball.y, ball.r
          );
          g.addColorStop(0, "#ffffff");
          g.addColorStop(.16, "#a8f4ff");
          g.addColorStop(.58, "#49c8f0");
          g.addColorStop(1, "#2671c9");

          ctx.beginPath();
          ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
          ctx.fillStyle = g;
          ctx.fill();
          ctx.strokeStyle = "#c7f8ff";
          ctx.lineWidth = 1.5;
          ctx.stroke();
        }
      }

      canvas.addEventListener("pointerdown", (event) => {
        const rect = canvas.getBoundingClientRect();
        const x = (event.clientX - rect.left) * w / rect.width;
        const y = (event.clientY - rect.top) * h / rect.height;
        addBall(x, y, (Math.random() - .5) * 3, -Math.random() * 3);
      });

      document.getElementById("drop").addEventListener("click", () => {
        addBall(
          w / 2 + (Math.random() - .5) * 160,
          28,
          (Math.random() - .5) * 4,
          0
        );
      });

      document.getElementById("clear").addEventListener("click", clear);

      document.getElementById("play").addEventListener("click", (event) => {
        running = !running;
        event.currentTarget.textContent = running ? "Pause" : "Play";
        lastTime = performance.now();
      });

      window.sim = {
        w,
        h,
        balls: () => ballsList.map(({ x, y, vx, vy, r }) => ({ x, y, vx, vy, r })),
        addBall,
        clear,
        step
      };

      function animate(now) {
        const elapsed = Math.min(2, (now - lastTime) / 16.6667);
        lastTime = now;
        if (running) step(elapsed);
        requestAnimationFrame(animate);
      }

      draw();
      requestAnimationFrame(animate);
    })();
  </script>
</body>
</html>
